      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 11/18~20) 만 50~54세 수도권 거주 남녀) 캔맥주 맛테스트 설문조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.29. 10:56\n조회 150\n구독\n고유링크) 11/18~20) 만 50~54세 수도권 거주 남녀) 캔맥주 맛테스트 설문조사\n고유링크) 11/18~20) 만 25~54세 수도권 거주 남녀) 캔맥주 맛테스트 설문조사\n모집이 마감되면 링크가 열리지 않으니 참고 부탁드립니다 ~\n조사대상: 월 1회 이상 캔맥주를 직접 구매해서 집에서 음용하는 만 25~54세 수도권 거주 남녀\n진행일정: 11월 18일(수)~20일(금) 중 하루/ 시간 선택/ 추후 안내드립니다\n* 현재 10월에 한국리서치에서 진행되는 맥주 시음조사와 중복 참여 가능합니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n소요시간 1시간\n사례비 30,000원\n안내사항 음주 맛테스트이기 때문에 임신중,수유중,식이조절중,금주중인 경우 참여가 어렵습니다. 또한 대중교통 이용 부탁드립니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/824?refuser=23341&intro=2\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.29. 15:38 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n채용동향조사 온라인 조사-본문 표에 있는 회사에 근무하고 있는 채용 관련 업무 담당자(대리급 경력 3년 이상 남성)\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n고유링크) 11/18~20) 만 50~54세 수도권 거주 남녀) 캔맥주 맛테스트 설문조사\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n고유링크) 11/18~20) 만 40~49세 수도권 거주 남녀) 캔맥주 맛테스트 설문조사\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n고유링크) 11/18~20) 만 30~39세 수도권 거주 남녀) 캔맥주 맛테스트 설문조사\n좌담회알바좌담회카페\n26.10.29.\n댓글\n2\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
