      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/9~11) 만18세~65세 여성)최근 1~2년 이내 본인이 직접 해당 카테고리 가방/캐리어를 구매하여 실제 사용 중인 분\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.29. 11:33\n조회 305\n구독\n11/9~11) 만18세~65세 남녀)최근 1~2년 이내 본인이 직접 해당 카테고리 가방/캐리어를 구매하여 실제 사용 중인 분\n[그룹 1] 만 18세 ~ 30세 남녀 (라이프스타일 가방 사용자)\n백팩, 크로스백, 데일리 메신저백 등 라이프스타일 가방 실사용자\n[그룹 2] 만 31세 ~ 49세 남녀 (라이프스타일 가방 사용자)\n비즈니스 백팩, 브리프케이스, 데일리 캐주얼백 등 라이프스타일 가방 실사용자\n[그룹 3] 만 50세 ~ 65세 남녀 (여행용 캐리어 사용자)\n여행·출장용 하드/소프트 캐리어(Luggage) 실사용자\n날짜: 11월 9월 ~11일 중 하루\n시간: 오후 2시 또는 4시 조건에 따라 다름\n소요시간: 3시간~3시간 10분\n사례비:7만원\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://survey.ipsoskorea.com/s/AGxb78\n위 링크를 통해 지원해 주세요.\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n***중요 안내사항***\n구매내역에 대한 영수증을 요청드립니다.\n구매한 가방/캐리어에 대한 사진을 요청드립니다.\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.29. 15:33 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n안녕하세요~귀사에서 작성하신 폼으로 모집을 의뢰하실때는요~\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n11/9~11) 만18세~65세 여성)최근 1~2년 이내 본인이 직접 해당 카테고리 가방/캐리어를 구매하여 실제 사용 중인 분\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n11/9~11) 만18세~65세 남성)최근 1~2년 이내 본인이 직접 해당 카테고리 가방/캐리어를 구매하여 실제 사용 중인 분\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n채용동향조사 온라인 조사-SK가스(주) 에 근무하고 있는 채용 관련 업무 담당자(대리급 경력 3년 이상 남녀 )\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
