      "type": "좌담회",
      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n좌담회 공유\n앱 열기\n안녕하세요~귀사에서 작성하신 폼으로 모집을 의뢰하실때는요~\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.10.29. 11:38\n조회 151\n구독\n안녕하세요~\n귀사에서 작성하신 폼으로 모집을 의뢰하실때는요~\n저희카페 고유링크인 경우: 소개자 적는칸이 없어도 됩니다만\n저희카페 고유링크가 아닌경우: 첫번째 칸에 소개자이름 적는칸을 필수항목으로 만들어서\n보내주시면 바로 공지하겠습니다\n뒤에 있으면 확인을 위해 질문에 테스트 하는 사이 탈락하면 확인을 못합니다ㅠㅠ\n그럴경우 공지할수가 없으니 양해 바랍니다 ㅠ\n위와같이 첫번째칸에 소개자 송난주에 필수항목으로 기재할수 있도록 질문 문항에 추가해서 보내주시면 확인하고 바로 공지하겠습니다~\n\"혹시 고유 링크가 아닌 일반 링크로 전달해 주실 경우,\n전달 주체 확인을 위해 소개자 이름 칸을\n필수 입력값인 '필수 항목'으로 반드시 설정해서 보내주셔야 합니다. ㅠㅠ\n필수항목이 누락될 경우 처리가 지연될 수 있으니 꼭 필수 설정 후 발송 부탁드립니다 !\"\n번거로우시겠지만 발송 전 필수 항목 설정 여부를 꼭 점검해 주시기 바랍니다.\"\n고유링크&링크는 필수 아닌 선택사항입니다\n감사합니다 ~\n귀사의 무궁한 발전을 기원합니다 ~\n좌담회\n좌담회알바\n좌담회카페\n좌담회알바 좌담회카페\n중학생알바\n고등학생알바\n대학생알바\n직장인알바\n주부알바\n단기알바\nN잡알바\n투잡알바\n#N잡알바\n#투잡알바\n#단기알바\n#좌담회\n#좌담회알바\n#좌담회카페\n#좌담회알바좌담회카페\n#직장인알바\n#프리랜서알바\n#대학생알바\n좋아요\n2\n좋아요한 사람 목록으로 이동\n송파구 이웃은 지금 어떤 이야기 중일까?\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.10.29. 15:33 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n20세~30세 미혼여성) 스킨케어 관련 온라인 조사\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n안녕하세요~귀사에서 작성하신 폼으로 모집을 의뢰하실때는요~\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n11/9~11) 만18세~65세 여성)최근 1~2년 이내 본인이 직접 해당 카테고리 가방/캐리어를 구매하여 실제 사용 중인 분\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n11/9~11) 만18세~65세 남성)최근 1~2년 이내 본인이 직접 해당 카테고리 가방/캐리어를 구매하여 실제 사용 중인 분\n좌담회알바좌담회카페\n26.10.29.\n댓글\n1\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n2\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
